    --accent: #c62828;
    --green: #2e7d32;
    --orange: #e65100;
    --purple: #6a1b9a;
    --teal: #00695c;
    --bg: #f8f9fa;
    --card-bg: #ffffff;
    --text: #212121;
    --muted: #757575;
    --border: #e0e0e0;
    --radius: 10px;
    --shadow: 0 2px 8px rgba(0,0,0,0.08);
  }}

  * {{ margin:0; padding:0; box-sizing:border-box; }}
  body {{
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
  }}

  .container {{ max-width: 1200px; margin: 0 auto; padding: 20px 24px; }}

  /* ── Header ── */
  .report-header {{
    background: linear-gradient(135deg, var(--primary) 0%, #283593 100%);
    color: white;
    padding: 48px 40px;
    border-radius: var(--radius);
    margin-bottom: 32px;
    position: relative;
    overflow: hidden;
  }}
  .report-header::after {{
    content: '';
    position: absolute;
    top: -50%;
    right: -10%;
    width: 400px;
    height: 400px;
    background: radial-gradient(circle, rgba(255,255,255,0.06) 0%, transparent 70%);
    border-radius: 50%;
  }}
  .report-header h1 {{
    font-size: 2.4em;
    font-weight: 800;
    margin-bottom: 8px;
    position: relative;
    z-index: 1;
  }}
  .report-header .subtitle {{
    font-size: 1.1em;
    opacity: 0.9;
    font-weight: 300;
    position: relative;
    z-index: 1;
  }}
  .report-header .meta {{
    margin-top: 16px;
    font-size: 0.9em;
    opacity: 0.7;
    position: relative;
    z-index: 1;
  }}

  /* ── Section ── */
  .section {{
    background: var(--card-bg);
    border-radius: var(--radius);
    box-shadow: var(--shadow);
    padding: 32px;
    margin-bottom: 28px;
    border: 1px solid var(--border);
  }}
  .section h2 {{
    font-size: 1.5em;
    color: var(--primary);
    border-bottom: 3px solid var(--primary);
    padding-bottom: 10px;
    margin-bottom: 24px;
  }}
  .section h3 {{
    font-size: 1.15em;
    color: #37474f;
    margin: 24px 0 12px;
  }}
  .section p {{
    color: var(--muted);
    margin-bottom: 16px;
    max-width: 80ch;
  }}

  /* ── KPI Cards ── */
  .kpi-dashboard {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 20px;
    margin-bottom: 28px;
  }}
  .kpi-card {{
    background: var(--card-bg);
    border-radius: var(--radius);
    padding: 24px;
    text-align: center;
    box-shadow: var(--shadow);
    border: 1px solid var(--border);
    transition: transform 0.15s;
  }}
  .kpi-card:hover {{ transform: translateY(-2px); }}
  .kpi-card .kpi-value {{
    font-size: 2.6em;
    font-weight: 800;
    color: var(--primary);
    line-height: 1.1;
  }}
  .kpi-card .kpi-label {{
    font-size: 0.9em;
    color: var(--muted);
    margin-top: 6px;
    font-weight: 500;
  }}
  .kpi-card .kpi-desc {{
    font-size: 0.75em;
    color: #9e9e9e;
    margin-top: 4px;
  }}

  /* ── Charts ── */
  .chart-container {{
    margin: 20px 0;
    text-align: center;
    overflow-x: auto;
  }}
  .chart-container svg {{
    max-width: 100%;
    height: auto;
  }}

  /* ── Tables ── */
  .table-wrapper {{
    overflow-x: auto;
    margin: 16px 0;
  }}
  .data-table {{
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9em;
  }}
  .data-table th {{
    background: var(--primary);
    color: white;
    padding: 12px 14px;
    text-align: left;
    font-weight: 600;
    font-size: 0.85em;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }}
  .data-table td {{
    padding: 10px 14px;
    border-bottom: 1px solid var(--border);
  }}
  .data-table tr:hover td {{
    background: #f5f5f5;
  }}
  .data-table tbody tr:nth-child(even) td {{
    background: #fafafa;
  }}
  .data-table .num {{
    text-align: right;
    font-variant-numeric: tabular-nums;
  }}

  /* ── Highlight boxes ── */
  .insight-box {{
    background: linear-gradient(135deg, #e8eaf6 0%, #f5f5f5 100%);
    border-left: 4px solid var(--primary);
    padding: 14px 18px;
    margin: 16px 0;
    border-radius: 0 var(--radius) var(--radius) 0;
    font-size: 0.9em;
    color: #37474f;
  }}
  .insight-box strong {{ color: var(--primary); }}

  .grid-2 {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
  }}
  @media (max-width: 768px) {{ .grid-2 {{ grid-template-columns: 1fr; }} }}

  /* ── Footer ── */
  .report-footer {{
    text-align: center;
    color: var(--muted);
    font-size: 0.85em;
    padding: 24px;
    margin-top: 32px;
    border-top: 1px solid var(--border);
  }}

  /* ── Summary stat row ── */
  .stat-row {{
    display: flex;
    flex-wrap: wrap;
    gap: 16px;
    margin: 16px 0;
  }}
  .stat-item {{
    background: var(--bg);
    border-radius: 8px;
    padding: 14px 20px;
    text-align: center;
    min-width: 120px;
  }}
  .stat-item .val {{
    font-size: 1.4em;
    font-weight: 700;
    color: var(--primary);
  }}
  .stat-item .lbl {{
    font-size: 0.78em;
    color: var(--muted);
  }}
</style>
</head>
