def escape_html(s):
    return str(s).replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')

def df_to_html(df_obj):
    """Convert pandas DataFrame to HTML table rows."""
    rows = []
    rows.append('<thead><tr>')
    for col in df_obj.columns:
        rows.append(f'<th>{escape_html(col)}</th>')
    rows.append('</tr></thead>')
    rows.append('<tbody>')
    for _, row in df_obj.iterrows():
        rows.append('<tr>')
        for col in df_obj.columns:
            val = row[col]
            if isinstance(val, float):
                rows.append(f'<td class="num">{val:.1f}</td>')
            elif isinstance(val, int):
                rows.append(f'<td class="num">{val}</td>')
            else:
                rows.append(f'<td>{escape_html(val)}</td>')
        rows.append('</tr>')
    rows.append('</tbody>')
    return '\n'.join(rows)


